V numericMotion(const Document& d,const V& input){require(input.t==V::Obj,"motion must be an object");V p=V::makeObj();for(const auto& [key,v]:input.obj){if(v.t==V::Num)add(p,key.c_str(),number(input,key.c_str()));else{require(v.t==V::Str,"motion values must be numbers or expressions");bool ok=false;auto n=evalExpr(v.str,d.buildEnv(),&ok);require(ok&&std::isfinite(n),"invalid expression: "+key);add(p,key.c_str(),n);}}return p;}
struct Input{double rpm=0,torque=0;bool loaded=false;};
Input input(const V& a){Input i;i.rpm=number(a,"input_rpm");i.torque=number(a,"input_torque_Nm");i.loaded=a.find("input_torque_Nm")||a.find("input_power_W");require(!(a.find("input_torque_Nm")&&a.find("input_power_W")),"choose torque or power");require(std::abs(i.rpm)<=100000&&i.torque>=0,"invalid input speed/torque");if(a.find("input_power_W")){auto power=number(a,"input_power_W");require(power>=0&&std::abs(i.rpm)>1e-12,"power at standstill cannot determine torque; provide input_torque_Nm");i.torque=power?power/(std::abs(i.rpm)*2*K_PI/60):0;}return i;}
std::vector<double> choices(const V& a,const char* key){const auto& list=get(a,key);require(list.t==V::Arr&&!list.arr.empty()&&list.arr.size()<=8,std::string(key)+" requires 1..8 values");std::vector<double> out;for(const auto& v:list.arr){require(v.t==V::Num&&std::isfinite(v.num)&&v.num>0&&v.num<=1000,"invalid module/pitch option");out.push_back(v.num);}std::sort(out.begin(),out.end());out.erase(std::unique(out.begin(),out.end()),out.end());return out;}
V stagesReport(const V& stages,const V& args){require(stages.t==V::Arr&&!stages.arr.empty()&&stages.arr.size()<=16,"stages must contain 1..16 pairs");Input start=input(args);double rpm=start.rpm,torque=start.torque,ratio=1,eta=1,maxDiameter=0,totalCenter=0;bool loaded=start.loaded,ideal=flag(args,"assume_ideal_efficiency");V rows=V::makeArr();for(const auto& stage:stages.arr){keys(stage,{"kind","motion"});auto kind=text(stage,"kind");auto pair=evaluateTransmissionPair(kind,get(stage,"motion"));V row=V::makeObj();row.set("kind",V::makeStr(kind));row.set("motion",get(stage,"motion"));row.set("geometry",pair);if(!get(pair,"efficiency_declared").b&&!ideal)loaded=false;row.set("load_available",V::makeBool(loaded));if(loaded){V load=transmissionLoad(pair,rpm,torque);row.set("load",load);torque=number(load,"output_torque_Nm");}ratio*=number(pair,"ratio",1);rpm*=number(pair,"ratio",1);eta*=number(pair,"efficiency",1);require(std::isfinite(rpm)&&std::abs(rpm)<=1e8&&std::isfinite(ratio)&&std::abs(ratio)>1e-12,"stage chain exceeds numerical range");add(row,"output_rpm",rpm);maxDiameter=std::max({maxDiameter,number(pair,"pitch_diameter_a_mm"),number(pair,"pitch_diameter_b_mm")});totalCenter+=pair.find("nominal_center_distance_mm")?number(pair,"nominal_center_distance_mm"):number(pair,"observed_center_distance_mm");rows.arr.push_back(row);}
    V report=V::makeObj();report.set("stages",rows);add(report,"signed_ratio",ratio);add(report,"reduction_ratio",1/std::abs(ratio));add(report,"output_rpm",rpm);add(report,"max_pitch_diameter_mm",maxDiameter);add(report,"sum_center_distances_mm",totalCenter);report.set("load_available",V::makeBool(loaded));if(loaded){add(report,"output_torque_Nm",torque);add(report,"overall_efficiency",eta);add(report,"output_power_W",torque*std::abs(rpm)*2*K_PI/60);}report.set("geometry_verified",V::makeBool(false));report.set("manufacturing_qualified",V::makeBool(false));return report;
}
struct Pair{int a=0,b=0;double reduction=1;};
struct Ranked{V candidate;std::tuple<double,double,int,double> score;};
V optimize(const Document& d,u64 revision,const V& args){
    const auto kind=text(args,"kind");require(kind=="gear"||kind=="chain"||kind=="belt","optimizer supports external gears, chain or synchronous belt pairs");double target=number(args,"target_reduction"),tolerance=number(args,"relative_error",.01);require(target>=1e-4&&target<=10000&&tolerance>=0&&tolerance<=.25,"invalid target reduction or relative error");
    double low=number(args,"min_teeth",18),high=number(args,"max_teeth",80);require(low>=4&&high<=1000&&low<=high&&high-low<=127&&low==std::floor(low)&&high==std::floor(high),"search needs integer teeth 4..1000 across at most 128 values");
    const double maxStageValue=number(args,"max_stages",2),minStageValue=number(args,"min_stages",1);require(minStageValue>=1&&maxStageValue<=2&&minStageValue<=maxStageValue&&std::floor(maxStageValue)==maxStageValue&&std::floor(minStageValue)==minStageValue,"search supports one or two stages");const int maxStages=(int)maxStageValue,minStages=(int)minStageValue;
    const auto modules=choices(args,kind=="gear"?"modules_mm":"pitches_mm");const auto second=args.find("second_stage_modules_mm")?choices(args,"second_stage_modules_mm"):std::vector<double>{};require(second.empty()||kind=="gear","second-stage modules require gears");
    std::vector<std::string> forms;if(kind=="gear"){if(args.find("forms")){const auto& f=get(args,"forms");require(f.t==V::Arr&&!f.arr.empty()&&f.arr.size()<=4,"forms needs 1..4 gear forms");for(const auto& v:f.arr){require(v.t==V::Str&&(v.str=="spur"||v.str=="helical"||v.str=="herringbone"||v.str=="double_helical"),"unsupported gear form");forms.push_back(v.str);}}else forms={"spur"};require(number(args,"face_width_mm")>0,"face_width_mm is required");}else{forms={"timing"};require(number(args,"center_distance_mm")>0,"chain/belt search needs declared centre distance");}
    if(args.find("max_axial_force_N")||args.find("min_contact_ratio")||args.find("allowable_bending_MPa"))require(kind=="gear","axial/contact/bending bounds require gears");if(args.find("allowable_chain_pull_N"))require(kind=="chain","chain pull bound requires chain search");for(auto key:{"min_engaged_teeth","max_polygonal_speed_variation_fraction"})if(args.find(key))require(number(args,key)>=0,"invalid engagement/ripple bound");if(args.find("max_polygonal_speed_variation_fraction"))require(kind=="chain"&&number(args,"max_polygonal_speed_variation_fraction")<=1,"polygonal bound is a chain fraction 0..1");if(args.find("min_engaged_teeth"))require(kind!="gear","engagement bound is for chain/timing belt");if(args.find("allowable_belt_tension_N"))require(kind=="belt"&&args.find("pretension_N"),"belt tension bound requires pretension");const auto objective=text(args,"objective",false);require(objective.empty()||objective=="min_max_diameter"||objective=="min_total_centers"||objective=="min_ratio_error","unknown objective");
    const double maxDiameter=number(args,"max_pitch_diameter_mm",1e9),maxCenter=number(args,"max_center_distance_mm",1e9),maxTotal=number(args,"max_total_centers_mm",1e9),minTorque=number(args,"min_output_torque_Nm"),minContact=number(args,"min_contact_ratio"),maxAxial=number(args,"max_axial_force_N",1e12);require(maxDiameter>0&&maxCenter>0&&maxTotal>0&&minTorque>=0&&minContact>=0&&maxAxial>=0,"invalid optimization bounds");
    const double directionValue=number(args,"output_direction");require(directionValue==-1||directionValue==0||directionValue==1,"output_direction must be -1, 0 or 1");const int direction=(int)directionValue;
    Input power=input(args);if(minTorque>0||args.find("max_axial_force_N")||args.find("allowable_chain_pull_N")||args.find("allowable_belt_tension_N"))require(power.loaded&&args.find("efficiency"),"load constraints require input torque/power and an explicit efficiency");
    double limitValue=number(args,"limit",8);require(limitValue>=1&&limitValue<=32&&limitValue==std::floor(limitValue),"limit must be 1..32");const size_t limit=(size_t)limitValue;
    std::vector<Pair> pairs;for(int a=(int)low;a<=(int)high;++a)for(int b=(int)low;b<=(int)high;++b)pairs.push_back({a,b,(double)b/a});std::sort(pairs.begin(),pairs.end(),[](const Pair& a,const Pair& b){return std::tie(a.reduction,a.a,a.b)<std::tie(b.reduction,b.a,b.b);});
    const auto control=captureNativeRequestControl();if(control.cancelled&&control.cancelled())throw std::runtime_error("MECHANICAL_CANCELLED: transmission optimization stopped");const auto sourceHash=iterationSha256(documentToJson(d,false,false));size_t examined=0,feasible=0,pruned=0;std::vector<Ranked> best;std::map<std::string,Ranked> groupBest;
    auto motion=[&](Pair pair,double scale,const std::string& form){V p=V::makeObj();add(p,"teeth_a",pair.a);add(p,"teeth_b",pair.b);if(args.find("efficiency"))add(p,"efficiency",number(args,"efficiency"));add(p,"service_factor",number(args,"service_factor",1));if(kind=="gear"){add(p,"module_mm",scale);add(p,"face_width_mm",number(args,"face_width_mm"));add(p,"pressure_angle_deg",number(args,"pressure_angle_deg",20));double beta=form=="spur"?0:number(args,"helix_angle_deg");require(form=="spur"||std::abs(beta)>0,"helical search requires helix_angle_deg");add(p,"helix_angle_deg",beta);add(p,"helix_b_deg",-beta);add(p,"internal",0);add(p,"double_helical",0);add(p,"center_gap_mm",0);if(form=="herringbone"||form=="double_helical"){add(p,"double_helical",1);add(p,"center_gap_mm",form=="herringbone"?0:number(args,"center_gap_mm",1));if(args.find("left_load_fraction"))add(p,"left_load_fraction",number(args,"left_load_fraction"));}for(auto k:{"lewis_factor_a","lewis_factor_b","allowable_bending_MPa"})if(args.find(k))add(p,k,number(args,k));}else{add(p,"pitch_mm",scale);add(p,"center_distance_mm",number(args,"center_distance_mm"));if(kind=="chain"&&args.find("allowable_chain_pull_N"))add(p,"allowable_chain_pull_N",number(args,"allowable_chain_pull_N"));if(kind=="belt"){add(p,"synchronous",1);add(p,"crossed",0);for(auto key:{"pretension_N","allowable_belt_tension_N"})if(args.find(key))add(p,key,number(args,key));}}return p;};
    auto consider=[&](Pair first,const Pair* next,double scale,double secondScale,const std::string& form){if(++examined>2000000)throw std::runtime_error("MECHANICAL_SEARCH_CAPACITY: narrow tooth/module/error ranges");if((examined&1023)==0&&control.cancelled&&control.cancelled())throw std::runtime_error("MECHANICAL_CANCELLED: transmission optimization stopped");const int count=next?2:1;const double reduction=first.reduction*(next?next->reduction:1),relative=std::abs(reduction-target)/target;const int sign=kind=="gear"&&count%2?-1:1;if(relative>tolerance||(direction&&direction!=sign))return;
        V stages=V::makeArr();double maxD=0,totalC=0;for(int index=0;index<count;++index){Pair pair=index?*next:first;double m=index?secondScale:scale;double beta=kind=="gear"&&form!="spur"?deg2rad(number(args,"helix_angle_deg")):0;require(std::abs(beta)<K_PI/3,"helix angle exceeds supported range");double da=kind=="gear"?(m/std::cos(beta))*pair.a:kind=="chain"?m/std::sin(K_PI/pair.a):m*pair.a/K_PI,db=kind=="gear"?(m/std::cos(beta))*pair.b:kind=="chain"?m/std::sin(K_PI/pair.b):m*pair.b/K_PI;double requestedCenter=index&&args.find("second_stage_center_mm")?number(args,"second_stage_center_mm"):number(args,"center_distance_mm");double center=kind=="gear"?(da+db)/2:requestedCenter;if(kind=="gear"&&args.find("center_distance_mm")){require(requestedCenter>0&&number(args,"center_tolerance_mm",1e-5)>0,"positive centre target/tolerance required");if(std::abs(center-requestedCenter)>number(args,"center_tolerance_mm",1e-5))return;}if(std::max(da,db)>maxDiameter||center>maxCenter||(kind!="gear"&&center<=(da+db)/2))return;if(kind=="gear"&&!flag(args,"allow_undercut")){double threshold=2/std::pow(std::sin(deg2rad(number(args,"pressure_angle_deg",20))),2);if(std::min(pair.a,pair.b)/std::pow(std::cos(beta),3)<threshold)return;}maxD=std::max({maxD,da,db});totalC+=center;V stage=V::makeObj();stage.set("kind",V::makeStr(kind));auto spec=motion(pair,m,form);if(args.find("center_distance_mm"))spec.set("center_distance_mm",V::makeNum(requestedCenter));stage.set("motion",spec);stages.arr.push_back(stage);}
        auto preliminary=std::make_tuple(objective=="min_ratio_error"?relative:objective=="min_total_centers"?totalC:maxD,relative,count,totalC);const auto group=form+"/"+std::to_string(count);if(best.size()==limit&&preliminary>=best.back().score&&groupBest.count(group)&&preliminary>=groupBest.at(group).score){++pruned;return;}V result=stagesReport(stages,args);if(number(result,"sum_center_distances_mm")>maxTotal||(minTorque>0&&number(result,"output_torque_Nm")<minTorque))return;
        for(const auto& stage:get(result,"stages").arr){const auto& geometry=get(stage,"geometry"),&load=get(stage,"load");if(args.find("min_engaged_teeth")&&kind!="gear"&&(number(geometry,"engaged_teeth_a")<number(args,"min_engaged_teeth")||number(geometry,"engaged_teeth_b")<number(args,"min_engaged_teeth")))return;if(kind=="chain"&&args.find("max_polygonal_speed_variation_fraction")&&number(geometry,"driver_polygonal_speed_variation_fraction")>number(args,"max_polygonal_speed_variation_fraction"))return;for(auto key:{"chain_pull_pass","belt_tension_pass","slack_side_positive"})if(load.find(key)&&!get(load,key).b)return;if(kind=="gear"){double contact=geometry.find("total_contact_ratio_per_half")?number(geometry,"total_contact_ratio_per_half"):number(geometry,"total_contact_ratio",number(geometry,"transverse_contact_ratio"));if(contact<minContact)return;if(args.find("max_axial_force_N")){if(number(get(stage,"motion"),"double_helical")==1){require(args.find("left_load_fraction"),"double-helical axial constraint requires explicit left_load_fraction");if(number(load,"net_axial_force_magnitude_N")>maxAxial)return;}else if(number(load,"axial_force_magnitude_N")>maxAxial)return;}if(load.find("lewis_bending_pass")&&!get(load,"lewis_bending_pass").b)return;}}
        ++feasible;result.set("topology",V::makeStr(next?"compound_two_stage":"single_stage"));result.set("form",V::makeStr(form));add(result,"relative_ratio_error",relative);add(result,"source_revision",revision);result.set("source_authoring_sha256",V::makeStr(sourceHash));result.set("candidate_id",V::makeStr(hash(result)));
        auto score=std::make_tuple(objective=="min_ratio_error"?relative:objective=="min_total_centers"?number(result,"sum_center_distances_mm"):number(result,"max_pitch_diameter_mm"),relative,count,number(result,"sum_center_distances_mm"));if(!groupBest.count(group)||score<groupBest.at(group).score)groupBest[group]=Ranked{result,score};best.push_back({std::move(result),score});std::stable_sort(best.begin(),best.end(),[](const auto& a,const auto& b){return a.score<b.score;});if(best.size()>limit)best.pop_back();
    };
    for(const auto& form:forms){auto check=motion(Pair{(int)low,(int)low,1},modules.front(),form);check.obj.erase(std::remove_if(check.obj.begin(),check.obj.end(),[](const auto& field){return field.first=="center_distance_mm";}),check.obj.end());evaluateTransmissionPair(kind,check);}
    if(args.find("allowable_bending_MPa"))require(power.loaded&&args.find("efficiency")&&args.find("lewis_factor_a")&&args.find("lewis_factor_b"),"bending constraints need load, efficiency and both caller-supplied Lewis factors");
    for(const auto& form:forms)for(double module:modules){if(minStages==1)for(const auto& pair:pairs)consider(pair,nullptr,module,module,form);if(maxStages==2)for(const auto& first:pairs){double lo=target*(1-tolerance)/first.reduction,hi=target*(1+tolerance)/first.reduction;auto begin=std::lower_bound(pairs.begin(),pairs.end(),lo-1e-12,[](const Pair& p,double value){return p.reduction<value;});for(auto it=begin;it!=pairs.end()&&it->reduction<=hi+1e-12;++it){if(second.empty())consider(first,&*it,module,module,form);else for(double m:second)consider(first,&*it,module,m,form);}}}
    V report=V::makeObj(),candidates=V::makeArr(),alternatives=V::makeArr();for(auto& [group,best]:groupBest)alternatives.arr.push_back(best.candidate);report.set("best_by_form_and_topology",alternatives);for(auto& item:best)candidates.arr.push_back(std::move(item.candidate));report.set("status",V::makeStr(candidates.arr.empty()?"no_feasible_candidate":"ranked_candidates"));report.set("candidates",candidates);if(!candidates.arr.empty())report.set("best",candidates.arr.front());add(report,"examined",examined);add(report,"feasible_evaluated",feasible);add(report,"objective_bound_pruned",pruned);report.set("search_complete",V::makeBool(true));report.set("optimality_scope",V::makeStr("ranked enumeration with objective-bound pruning within explicit integer/module/form bounds, zero-shift analytic screening; no global geometric or fatigue optimum"));report.set("compound_contract",V::makeStr("two meshes share one coaxial intermediate occurrence, or separate occurrences joined by shaft mates; no CAD or positioning is created automatically"));report.set("form_search",V::makeStr("one common gear form across stages; mixed forms may be analyzed explicitly with stages"));report.set("module_search",V::makeStr(second.empty()?"common module/pitch across stages":"explicit first/second stage module grids"));return report;
}
V prepare(const Document& d,u64 revision,const V& args){
    const auto& candidate=get(args,"candidate");require(candidate.t==V::Obj,"candidate required");V unsignedCandidate=candidate;unsignedCandidate.obj.erase(std::remove_if(unsignedCandidate.obj.begin(),unsignedCandidate.obj.end(),[](const auto& item){return item.first=="candidate_id";}),unsignedCandidate.obj.end());require(text(candidate,"candidate_id")==hash(unsignedCandidate),"candidate fingerprint differs");if(number(candidate,"source_revision")!=revision||text(candidate,"source_authoring_sha256")!=iterationSha256(documentToJson(d,false,false)))throw std::runtime_error("MECHANICAL_CANDIDATE_STALE: recalculate against current authoring");
    const auto& stages=get(candidate,"stages"),&bindings=get(args,"bindings");require(stages.t==V::Arr&&!stages.arr.empty()&&stages.arr.size()<=2,"candidate stage count invalid");keys(bindings,{"parameters","mates"});std::map<std::string,double> parameterValues;std::map<std::pair<size_t,std::string>,std::string> linked;
    const auto& parameters=get(bindings,"parameters");require(parameters.isNull()||(parameters.t==V::Arr&&parameters.arr.size()<=32),"parameter bindings must be an array");for(const auto& b:parameters.arr){keys(b,{"parameter","stage","field"});auto name=text(b,"parameter"),field=text(b,"field");double index=number(b,"stage");require(index>=0&&index<stages.arr.size()&&index==std::floor(index),"invalid bound stage");require(std::any_of(d.params.begin(),d.params.end(),[&](const auto& p){return p.name==name;}),"bound parameter not found: "+name);const auto& stage=stages.arr[(size_t)index];auto geometry=evaluateTransmissionPair(text(stage,"kind"),get(stage,"motion"));const V* v=get(stage,"motion").find(field.c_str());if(!v)v=geometry.find(field.c_str());require(v&&v->t==V::Num,"bound field is not a numeric design output");if(parameterValues.count(name))require(parameterValues[name]==v->num,"one parameter received conflicting stage values");parameterValues[name]=v->num;linked[{(size_t)index,field}]=name;}
    V commands=V::makeArr(),mateCommands=V::makeArr();std::set<u64> boundMates;std::map<size_t,const AssemblyMate*> mapped;const auto& mates=get(bindings,"mates");require(mates.t==V::Arr&&mates.arr.size()==stages.arr.size(),"bind every candidate stage to one existing mate");bool kinematicsOnly=flag(args,"kinematics_only");
    for(const auto& binding:mates.arr){keys(binding,{"mate_id","stage"});double index=number(binding,"stage"),id=number(binding,"mate_id");require(index>=0&&index<stages.arr.size()&&index==std::floor(index)&&id>=1&&id==std::floor(id),"invalid mate binding");const AssemblyMate* mate=nullptr;for(const auto& m:d.mates)if(m.id==(u64)id)mate=&m;require(mate&&boundMates.insert(mate->id).second&&mapped.emplace((size_t)index,mate).second,"missing or duplicate bound mate/stage");const auto& stage=stages.arr[(size_t)index];require(mate->type==text(stage,"kind"),"candidate and existing mate types differ");V motion=get(stage,"motion");evaluateTransmissionPair(mate->type,motion);
        for(auto& [key,value]:motion.obj){auto link=linked.find({(size_t)index,key});auto previous=mate->motion.find(key);if(link!=linked.end())value=V::makeStr(link->second);else if(previous!=mate->motion.end()&&std::any_of(d.params.begin(),d.params.end(),[&](const auto& p){return p.name==previous->second;})){auto name=previous->second;if(parameterValues.count(name))require(parameterValues[name]==value.num,"shared parameter conflicts across stages");parameterValues[name]=value.num;value=V::makeStr(name);}else if(!kinematicsOnly&&(key=="teeth_a"||key=="teeth_b"||key=="module_mm"||key=="pitch_mm"||key=="helix_angle_deg"||key=="helix_b_deg"||key=="double_helical"||key=="internal"||key=="synchronous"||key=="crossed")){bool ok=false;double old=previous==mate->motion.end()?0:evalExpr(previous->second,d.buildEnv(),&ok);require((ok||(!mate->motion.count(key)&&value.num==0))&&std::abs(old-value.num)<=1e-12,"geometry change requires a parameter binding for "+key+"; use kinematics_only only for explicit ideal-coupling edits");}}
        for(const auto& [key,value]:mate->motion)if(!motion.find(key.c_str()))motion.set(key,V::makeStr(value));if(mate->type=="gear"&&number(get(stage,"motion"),"double_helical")==0)motion.obj.erase(std::remove_if(motion.obj.begin(),motion.obj.end(),[](const auto& item){return item.first=="left_load_fraction";}),motion.obj.end());if(mate->type=="gear"&&!kinematicsOnly)motion.set("enforce_center_distance",V::makeNum(1));V command=V::makeObj();command.set("op",V::makeStr("mate.edit"));add(command,"id",mate->id);command.set("motion",motion);mateCommands.arr.push_back(command);
    }
    if(mapped.size()==2){u64 from=mapped.at(0)->b,to=mapped.at(1)->a;std::set<u64> seen{from};std::vector<u64> queue{from};for(size_t i=0;i<queue.size();++i)for(const auto& mate:d.mates)if(mate.type=="shaft"&&mate.a==queue[i]&&seen.insert(mate.b).second)queue.push_back(mate.b);require(seen.count(to),"two stages must share a compound occurrence or an authored coaxial shaft path");}
    for(const auto& [name,value]:parameterValues){V c=V::makeObj();c.set("op",V::makeStr("param.set"));c.set("name",V::makeStr(name));add(c,"expr",value);commands.arr.push_back(c);}commands.arr.insert(commands.arr.end(),mateCommands.arr.begin(),mateCommands.arr.end());V preview=V::makeObj();add(preview,"expected_revision",revision);preview.set("commands",commands);V report=V::makeObj();report.set("preview_arguments",preview);report.set("kinematics_only",V::makeBool(kinematicsOnly));report.set("geometry_verified",V::makeBool(false));report.set("next_action",V::makeStr("Inspect parameter dependencies and the actual tooth geometry; doc_preview must recompute CAD and mates, then explicitly doc_apply its accepted candidate. Bindings do not certify physical tooth count or contact."));return report;
}
